<template><Form :label-width="145" class="s1-form" @submit.native.prevent><FormItem v-for="field in fields" :key="field.key" :label="field.label" :required="field.required"><Select v-if="field.type==='select'||field.type==='multi'" :value="value[field.key]" :multiple="field.type==='multi'" :disabled="disabled||field.disabled" filterable clearable @on-change="set(field,$event)"><Option v-for="option in field.options||[]" :key="option.value" :value="option.value">{{option.label}}</Option></Select><i-switch v-else-if="field.type==='boolean'" :value="!!value[field.key]" :disabled="disabled||field.disabled" @on-change="set(field,$event)"/><InputNumber v-else-if="field.type==='integer'" :value="value[field.key]==null?null:value[field.key]" :min="field.min==null?0:field.min" :max="field.max==null?Number.MAX_SAFE_INTEGER:field.max" :precision="0" :disabled="disabled||field.disabled" @on-change="set(field,$event)"/><Input v-else :value="value[field.key]" :type="field.type==='textarea'?'textarea':'text'" :maxlength="field.max||2000" :rows="3" :disabled="disabled||field.disabled" :placeholder="field.placeholder||''" @input="set(field,$event)"/><p v-if="field.help" class="s1-help">{{field.help}}</p></FormItem></Form></template>
<script>export default {props:{value:{type:Object,required:true},fields:{type:Array,required:true},disabled:Boolean},methods:{set(field,value){this.$emit('input',{...this.value,[field.key]:value});}}};</script>
<style scoped>.s1-form{max-width:850px}.s1-help{color:#636b78;line-height:1.5;padding-top:6px}.ivu-input-number{width:220px}</style>
